// Merge all data from the 4 parallel API calls
const activity = $('Get Activity Details').first().json;
const streamsRaw = $('Get Streams').first().json;
const intervalsRaw = $('Get Intervals').first().json;
const wellness = $('Get Wellness').first().json;
const user = $('Loop Over Users').item.json;

const type = (activity.type || '').toLowerCase();
const isSwim = type.includes('swim');
const isRun = type.includes('run');
const isBike = type.includes('ride') || type.includes('bike') || type.includes('cycling') || type.includes('virtualride');

// --- Parse streams into arrays ---
const streams = {};
if (Array.isArray(streamsRaw)) {
  for (const s of streamsRaw) {
    if (s.type && s.data) streams[s.type] = s.data;
  }
} else if (streamsRaw && typeof streamsRaw === 'object') {
  // Sometimes returned as object with arrays directly
  for (const [key, val] of Object.entries(streamsRaw)) {
    if (Array.isArray(val)) streams[key] = val;
    else if (val && val.data) streams[key] = val.data;
  }
}

// --- Compute cardiac drift ---
let cardiacDrift = null;
const hr = streams.heartrate;
if (hr && hr.length > 20) {
  const quarter = Math.floor(hr.length / 4);
  const firstQ = hr.slice(0, quarter).filter(v => v > 0);
  const lastQ = hr.slice(-quarter).filter(v => v > 0);
  if (firstQ.length > 0 && lastQ.length > 0) {
    const avgFirst = firstQ.reduce((a, b) => a + b, 0) / firstQ.length;
    const avgLast = lastQ.reduce((a, b) => a + b, 0) / lastQ.length;
    cardiacDrift = ((avgLast - avgFirst) / avgFirst * 100).toFixed(1);
  }
}

// --- Compute power decoupling (first half vs second half) ---
let powerDecoupling = null;
const watts = streams.watts;
if (watts && hr && watts.length > 20) {
  const mid = Math.floor(watts.length / 2);
  const pw1 = watts.slice(0, mid).filter(v => v > 0);
  const pw2 = watts.slice(mid).filter(v => v > 0);
  const hr1 = hr.slice(0, mid).filter(v => v > 0);
  const hr2 = hr.slice(mid).filter(v => v > 0);
  if (pw1.length && pw2.length && hr1.length && hr2.length) {
    const ef1 = (pw1.reduce((a, b) => a + b, 0) / pw1.length) / (hr1.reduce((a, b) => a + b, 0) / hr1.length);
    const ef2 = (pw2.reduce((a, b) => a + b, 0) / pw2.length) / (hr2.reduce((a, b) => a + b, 0) / hr2.length);
    powerDecoupling = ((ef1 - ef2) / ef1 * 100).toFixed(1);
  }
}

// --- Compute pace/speed decoupling for run/swim ---
let paceDecoupling = null;
const speed = streams.velocity_smooth;
if (speed && hr && speed.length > 20 && !isBike) {
  const mid = Math.floor(speed.length / 2);
  const sp1 = speed.slice(0, mid).filter(v => v > 0);
  const sp2 = speed.slice(mid).filter(v => v > 0);
  const hr1 = hr.slice(0, mid).filter(v => v > 0);
  const hr2 = hr.slice(mid).filter(v => v > 0);
  if (sp1.length && sp2.length && hr1.length && hr2.length) {
    const ef1 = (sp1.reduce((a, b) => a + b, 0) / sp1.length) / (hr1.reduce((a, b) => a + b, 0) / hr1.length);
    const ef2 = (sp2.reduce((a, b) => a + b, 0) / sp2.length) / (hr2.reduce((a, b) => a + b, 0) / hr2.length);
    paceDecoupling = ((ef1 - ef2) / ef1 * 100).toFixed(1);
  }
}

// --- Format pace correctly per sport ---
let paceStr = null;
if (activity.average_speed && activity.average_speed > 0) {
  if (isSwim) {
    // Swim: pace per 100m
    const secsPer100 = 100 / activity.average_speed;
    const mins = Math.floor(secsPer100 / 60);
    const secs = Math.round(secsPer100 % 60);
    paceStr = `${mins}:${String(secs).padStart(2, '0')}/100m`;
  } else if (isRun) {
    // Run: pace per km
    const secsPerKm = 1000 / activity.average_speed;
    const mins = Math.floor(secsPerKm / 60);
    const secs = Math.round(secsPerKm % 60);
    paceStr = `${mins}:${String(secs).padStart(2, '0')}/km`;
  } else if (isBike) {
    paceStr = `${(activity.average_speed * 3.6).toFixed(1)} km/h`;
  }
}

// --- Format intervals ---
let intervalsSummary = [];
const intervals = intervalsRaw?.icu_intervals || [];
const workIntervals = intervals.filter(i => i.type === 'WORK');
if (workIntervals.length > 0) {
  const powers = workIntervals.map(i => i.average_watts).filter(Boolean);
  const hrs = workIntervals.map(i => i.average_heartrate).filter(Boolean);
  const paces = workIntervals.map(i => i.average_speed).filter(Boolean);

  for (const [idx, interval] of workIntervals.entries()) {
    let line = `Rep ${idx + 1}: ${Math.round(interval.elapsed_time / 60 * 10) / 10}min`;
    if (interval.distance) line += `, ${(interval.distance / (isSwim ? 1 : 1000)).toFixed(isSwim ? 0 : 2)}${isSwim ? 'm' : 'km'}`;
    if (interval.average_watts) line += `, ${Math.round(interval.average_watts)}W`;
    if (interval.average_heartrate) line += `, ${Math.round(interval.average_heartrate)}bpm`;
    if (interval.average_speed && isSwim) {
      const p = 100 / interval.average_speed;
      line += `, ${Math.floor(p/60)}:${String(Math.round(p%60)).padStart(2,'0')}/100m`;
    } else if (interval.average_speed && isRun) {
      const p = 1000 / interval.average_speed;
      line += `, ${Math.floor(p/60)}:${String(Math.round(p%60)).padStart(2,'0')}/km`;
    }
    if (interval.decoupling != null) line += `, decoupling: ${(interval.decoupling * 100).toFixed(1)}%`;
    intervalsSummary.push(line);
  }

  // Consistency stats
  if (powers.length > 1) {
    const avg = powers.reduce((a, b) => a + b, 0) / powers.length;
    const stddev = Math.sqrt(powers.map(p => (p - avg) ** 2).reduce((a, b) => a + b, 0) / powers.length);
    const cv = (stddev / avg * 100).toFixed(1);
    intervalsSummary.push(`Power consistency: avg ${Math.round(avg)}W, CV ${cv}%`);
  }
  if (paces.length > 1 && (isSwim || isRun)) {
    const div = isSwim ? 100 : 1000;
    const paceSecs = paces.map(s => div / s);
    const avg = paceSecs.reduce((a, b) => a + b, 0) / paceSecs.length;
    const stddev = Math.sqrt(paceSecs.map(p => (p - avg) ** 2).reduce((a, b) => a + b, 0) / paceSecs.length);
    const cv = (stddev / avg * 100).toFixed(1);
    intervalsSummary.push(`Pace consistency: CV ${cv}%`);
  }
}

// --- Cadence ---
let cadenceStr = null;
if (activity.average_cadence || activity.avg_run_cadence) {
  if (isRun) {
    const spm = Math.round((activity.avg_run_cadence || activity.average_cadence) * 2);
    cadenceStr = `${spm} spm`;
  } else if (isBike) {
    cadenceStr = `${Math.round(activity.average_cadence)} rpm`;
  } else if (isSwim) {
    cadenceStr = `${Math.round(activity.average_cadence)} strokes/min`;
  }
}

// --- Cadence variability from streams ---
let cadenceCV = null;
const cadStream = streams.cadence;
if (cadStream && cadStream.length > 20) {
  const nonZero = cadStream.filter(v => v > 0);
  if (nonZero.length > 10) {
    const avg = nonZero.reduce((a, b) => a + b, 0) / nonZero.length;
    const stddev = Math.sqrt(nonZero.map(c => (c - avg) ** 2).reduce((a, b) => a + b, 0) / nonZero.length);
    cadenceCV = (stddev / avg * 100).toFixed(1);
  }
}

// --- Build output ---
const sport = isSwim ? 'Swim' : isRun ? 'Run' : isBike ? 'Bike' : activity.type;

const result = {
  sport,
  activityName: activity.name,
  device: activity.device_name,
  durationMin: Math.round(activity.moving_time / 60),
  elapsedMin: Math.round(activity.elapsed_time / 60),
  distanceKm: activity.distance ? (activity.distance / 1000).toFixed(2) : null,
  distanceM: activity.distance ? Math.round(activity.distance) : null,
  pace: paceStr,
  cadence: cadenceStr,
  cadenceCV: cadenceCV ? `${cadenceCV}%` : null,

  // Power (bike mainly)
  avgPower: activity.avg_watts ? Math.round(activity.avg_watts) : null,
  normalizedPower: activity.weighted_avg_watts ? Math.round(activity.weighted_avg_watts) : null,
  maxPower: activity.max_watts ? Math.round(activity.max_watts) : null,
  variabilityIndex: activity.variability_index ? activity.variability_index.toFixed(2) : null,

  // HR
  avgHR: activity.average_heartrate ? Math.round(activity.average_heartrate) : null,
  maxHR: activity.max_heartrate ? Math.round(activity.max_heartrate) : null,
  hrZoneMins: activity.icu_hr_zone_times ? activity.icu_hr_zone_times.map(t => Math.round(t / 60)) : null,

  // Computed metrics
  cardiacDrift: cardiacDrift ? `${cardiacDrift}%` : null,
  powerDecoupling: powerDecoupling ? `${powerDecoupling}%` : null,
  paceDecoupling: paceDecoupling ? `${paceDecoupling}%` : null,

  // Training load
  tss: activity.icu_training_load ? Math.round(activity.icu_training_load) : null,
  intensityFactor: activity.intensity ? activity.intensity.toFixed(2) : null,
  trimp: activity.trimp ? Math.round(activity.trimp) : null,

  // Intervals
  intervalCount: workIntervals.length,
  intervals: intervalsSummary.length > 0 ? intervalsSummary : null,

  // Wellness context
  ctl: wellness?.ctl ? Math.round(wellness.ctl) : null,
  atl: wellness?.atl ? Math.round(wellness.atl) : null,
  tsb: (wellness?.ctl != null && wellness?.atl != null) ? Math.round(wellness.ctl - wellness.atl) : null,
  restingHR: wellness?.restingHR || null,
  sleepHours: wellness?.sleepSecs ? (wellness.sleepSecs / 3600).toFixed(1) : null,
  soreness: wellness?.soreness || null,
  fatigue: wellness?.fatigue || null,
  mood: wellness?.mood || null,
  hrv: wellness?.hrv || null
};

return [{ json: result }];

