- Date: {{ $today.toFormat('cccc, yyyy-MM-dd') }}
- Athlete: {{ $('Loop Over Users').item.json.Name }}
- Training Phase: {{ $('Loop Over Users').item.json['Training Phase'] }}
- Fitness Profile: {{ $('Loop Over Users').item.json['Fitness Profile'] }}

